import { useMemo, useState } from 'react'
import { Bookmark, History, Trash2, ArrowRight } from 'lucide-react'
import { useCatalog } from '../lib/catalog-context'
import Cover from '../components/Cover'
import { SeriesCard } from '../components/SeriesCard'
import { Button, StatusBadge, SectionHeader } from '../components/ui'
import { navigate, useRoute } from '../lib/router'
import { useStore } from '../lib/store'
import { cx, relativeDate, chapterHref } from '../lib/utils'

export default function Library() {
  const route = useRoute()
  const { series: catalog, loading } = useCatalog()
  const { library, toggleLibrary, progress, ratings } = useStore()
  const initialTab = route.query.get('tab') === 'history' ? 'history' : 'library'
  const [tab, setTab] = useState<'library' | 'history'>(initialTab)

  const savedSeries = useMemo(
    () =>
      library
        .map((id) => catalog.find((s) => s.id === id))
        .filter((s): s is (typeof catalog)[number] => !!s),
    [library, catalog],
  )

  const history = useMemo(
    () =>
      Object.values(progress)
        .sort((a, b) => b.updatedAt - a.updatedAt)
        .map((p) => {
          const s = catalog.find((x) => x.id === p.seriesId)
          const chapter = s?.chapters.find((c) => c.id === p.chapterId)
          return s && chapter ? { series: s, chapter, at: p.updatedAt } : null
        })
        .filter(Boolean) as { series: (typeof catalog)[number]; chapter: (typeof catalog)[number]['chapters'][number]; at: number }[],
    [progress, catalog],
  )

  const totalChaptersRead = Object.values(progress).reduce((n, p) => n + p.chapterNumber, 0)
  const ratedCount = Object.keys(ratings).length

  const tabs = [
    { key: 'library' as const, label: 'Library Titles', icon: Bookmark, count: savedSeries.length },
    { key: 'history' as const, label: 'Reading History', icon: History, count: history.length },
  ]

  return (
    <main className="mx-auto max-w-[1240px] animate-fade-up px-4 py-10 sm:px-6 lg:px-8">
      <div className="mb-8">
        <div className="eyebrow mb-2 text-accent">Account</div>
        <h1 className="text-3xl font-extrabold tracking-tight sm:text-4xl">My Library</h1>
        <p className="mt-2 text-ink-soft">Track reading progress, saved titles, and reading history.</p>
      </div>

      {/* Stats */}
      <div className="mb-8 grid grid-cols-2 gap-3 sm:grid-cols-4">
        <Stat label="Saved titles" value={String(savedSeries.length)} />
        <Stat label="Chapters read" value={String(totalChaptersRead)} />
        <Stat label="Series in progress" value={String(history.length)} />
        <Stat label="Chapters rated" value={String(ratedCount)} />
      </div>

      {/* Tabs */}
      <div className="mb-6 flex gap-2 border-b border-line pb-px">
        {tabs.map((t) => (
          <button
            key={t.key}
            onClick={() => setTab(t.key)}
            className={cx(
              'relative -mb-px inline-flex items-center gap-2 border-b-2 px-4 py-3 text-sm font-semibold transition-colors',
              tab === t.key
                ? 'border-accent text-ink'
                : 'border-transparent text-ink-soft hover:text-ink',
            )}
          >
            <t.icon width={15} height={15} />
            {t.label}
            {t.count > 0 && (
              <span className="rounded-full bg-ink/8 px-1.5 py-0.5 text-[10px] font-bold text-ink-soft">
                {t.count}
              </span>
            )}
          </button>
        ))}
      </div>

      {tab === 'library' ? (
        savedSeries.length === 0 ? (
          <EmptyLibrary />
        ) : (
          <>
            <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
              {savedSeries.map((s) => (
                <SeriesCard key={s.id} series={s} />
              ))}
            </div>
            <div className="mt-10 rounded-[16px] border border-line bg-paper-2/50 p-5">
              <SectionHeader eyebrow="Management" title="Quick Remove" />
              <div className="flex flex-wrap gap-2">
                {savedSeries.map((s) => (
                  <button
                    key={s.id}
                    onClick={() => toggleLibrary(s.id, s.title)}
                    className="inline-flex items-center gap-1.5 rounded-full border border-line-strong bg-paper px-3 py-1.5 text-xs font-medium text-ink-soft transition-colors hover:border-accent hover:text-accent"
                  >
                    <Trash2 width={12} height={12} />
                    {s.title}
                  </button>
                ))}
              </div>
            </div>
          </>
        )
      ) : history.length === 0 ? (
        <div className="rounded-[18px] border border-dashed border-line-strong bg-paper px-6 py-20 text-center">
          <History width={32} height={32} className="mx-auto text-ink-faint" />
          <div className="mt-3 text-lg font-bold">No active reading history</div>
          <p className="mx-auto mt-2 max-w-sm text-sm text-ink-soft">
            Open any chapter and your progress will be tracked here automatically.
          </p>
          <div className="mt-5">
            <Button onClick={() => navigate('/catalog')}>Browse Catalog</Button>
          </div>
        </div>
      ) : (
        <div className="space-y-3">
          {history.map(({ series: s, chapter, at }) => (
            <a
              key={s.id}
              href={chapterHref(s, chapter.number)}
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate(chapterHref(s, chapter.number))
              }}
              className="group flex items-center gap-4 rounded-[14px] border border-line bg-paper p-3 transition-all hover:-translate-y-0.5 hover:shadow-md"
            >
              <div className="h-[72px] w-14 shrink-0 overflow-hidden rounded-lg ring-1 ring-black/5">
                <Cover series={s} showTitle={false} rounded="rounded-lg" />
              </div>
              <div className="min-w-0 flex-1">
                <div className="flex flex-wrap items-center gap-2">
                  <h4 className="line-clamp-1 font-bold tracking-tight group-hover:text-accent">
                    {s.title}
                  </h4>
                  <StatusBadge status={s.status} />
                </div>
                <p className="mt-0.5 line-clamp-1 text-sm text-ink-soft">
                  Ch. {chapter.number} — {chapter.title}
                </p>
                <p className="mt-1 text-xs text-ink-faint">
                  Last opened {relativeDate(new Date(at).toISOString())}
                </p>
              </div>
              <span className="hidden shrink-0 items-center gap-1 rounded-full bg-ink/5 px-3 py-1.5 text-xs font-bold text-ink transition-colors group-hover:bg-accent group-hover:text-white sm:inline-flex">
                Continue <ArrowRight width={13} height={13} />
              </span>
            </a>
          ))}
        </div>
      )}
    </main>
  )
}

function EmptyLibrary() {
  return (
    <div className="rounded-[18px] border border-dashed border-line-strong bg-paper px-6 py-20 text-center">
      <Bookmark width={32} height={32} className="mx-auto text-ink-faint" />
      <div className="mt-3 text-lg font-bold">Your library is empty</div>
      <p className="mx-auto mt-2 max-w-sm text-sm text-ink-soft">
        Save series you love and they'll appear here for quick access and drop alerts.
      </p>
      <div className="mt-5 flex flex-wrap justify-center gap-3">
        <Button onClick={() => navigate('/catalog')}>Browse Catalog</Button>
        <Button variant="outline" onClick={() => navigate('/rankings')}>
          View Rankings
        </Button>
      </div>
    </div>
  )
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-[14px] border border-line bg-paper px-5 py-4">
      <div className="text-[1.75rem] font-extrabold leading-none tabular-nums">{value}</div>
      <div className="mt-2 text-xs font-medium text-ink-faint">{label}</div>
    </div>
  )
}
